parameters.jsCode:
const items = $input.all();
const formattedResults = [];

// Filter valid vehicles with an assigned user_id (process top active vehicles)
const validVehicles = items
  .map(item => item.json)
  .filter(v => v && v.id && v.user_id)
  .slice(0, 5);

for (const v of validVehicles) {
  const services = v.service_records || [];
  const diagnoses = v.fault_diagnoses || [];
  const maintenance = v.maintenance_schedules || [];
  const insurance = v.insurance_policies || [];
  const puc = v.puc_certificates || [];

  const overdueMaintenance = maintenance.filter(m => m.status === 'overdue' || m.status === 'due_soon');
  const recentDiagnoses = diagnoses.slice(0, 3);
  const recentServices = services.slice(0, 3);

  const promptContext = `Vehicle: ${v.year || ''} ${v.make || ''} ${v.model || ''} (VIN: ${v.vin || 'N/A'}, Odometer: ${v.odometer_km || 0} km)
Overdue/Due Maintenance (${overdueMaintenance.length}): ${overdueMaintenance.map(m => m.task_name + ' [' + m.status + ']').join(', ') || 'None'}
Recent Diagnoses (${recentDiagnoses.length}): ${recentDiagnoses.map(d => d.symptom + ' -> Cause: ' + (d.possible_cause || 'N/A')).join('; ') || 'None'}
Recent Services (${recentServices.length}): ${recentServices.map(s => s.service_type + ' on ' + (s.service_date || s.created_at || '')).join('; ') || 'None'}
Insurance Status: ${insurance.length > 0 ? 'Active (Expires ' + (insurance[0].expiry_date || 'N/A') + ')' : 'No policy'}
PUC Status: ${puc.length > 0 ? 'Expiry: ' + (puc[0].expiry_date || 'N/A') : 'No PUC'}`;

  formattedResults.push({
    json: {
      vehicle_id: v.id,
      user_id: v.user_id,
      vehicle_model: `${v.year || ''} ${v.make || ''} ${v.model || ''}`.trim(),
      prompt_context: promptContext,
      raw_vehicle: v
    }
  });
}

return formattedResults;

